        raise NotImplementedError("Subclasses must implement get_data")

    def export(self):
        try:
            data = self.get_data()
            if not data:
                return None
            if self.export_format == 'csv':
                return self._export_csv(data)
            elif self.export_format == 'xml':
                return self._export_xml(data)
            elif self.export_format == 'excel':
                return self._export_excel(data)
            else:
                raise ValueError(f"Unsupported export format: {self.export_format}")
        except Exception as e:
            raise RuntimeError(f"Export failed: {str(e)}") from e

    def _export_csv(self, data):
        output = StringIO()
        writer = csv.writer(output)
        writer.writerow(self.schema_class.headers)
        for row in data:
            writer.writerow(self.schema_class.to_csv_row(row))
        return output.getvalue()

    def _export_xml(self, data):
        root = ET.Element("exports")
        for row in data:
            item = ET.SubElement(root, "item")
            for field, value in self.schema_class.to_xml_row(row).items():
                ET.SubElement(item, field).text = str(value)
        return ET.tostring(root, encoding='unicode')

    def _export_excel(self, data):
        output = BytesIO()
        workbook = openpyxl.Workbook()
        sheet = workbook.active
        sheet.append(self.schema_class.headers)
        for row in data:
            sheet.append(self.schema_class.to_excel_row(row))
        workbook.save(output)
        return output.getvalue()

